[{"order":1,"type":"heading","text":"Middleware: Creating and Using Custom Middleware in Node.js"},{"order":2,"type":"paragraph","text":"Middleware functions are functions that have access to the request object (req), the response object (res), and the next middleware function in the application’s request-response cycle. Middleware functions can perform the following tasks: Execute any code. Make changes to the request and the response objects. End the request-response cycle. Call the next middleware function in the stack. If the current middleware function does not end the request-response cycle, it must call next() to pass control to the next middleware function. Otherwise, the request will be left hanging."},{"order":3,"type":"subheading","text":"Creating Custom Middleware"},{"order":4,"type":"paragraph","text":"To create custom middleware, you define a function that accepts three arguments: req, res, and next. This function will contain the logic you want to execute for each incoming request that passes through the middleware."},{"order":5,"type":"code","text":"// Example: Custom middleware to log request details
const myLogger = (req, res, next) => {
  console.log('Request URL:', req.url);
  console.log('Request Method:', req.method);
  next(); // Call the next middleware function
};

module.exports = myLogger;"},{"order":6,"type":"paragraph","text":"In this example, 'myLogger' is a middleware function that logs the request URL and method to the console. The 'next()' function is called to pass control to the next middleware in the chain."},{"order":7,"type":"subheading","text":"Using Custom Middleware"},{"order":8,"type":"paragraph","text":"To use custom middleware, you need to import it into your application and then apply it to specific routes or globally to all routes. You can apply middleware at the application level or at the route level."},{"order":9,"type":"code","text":"// Example: Applying middleware at the application level (applies to all routes)
const express = require('express');
const myLogger = require('./middleware/myLogger'); // Assuming myLogger.js is in a middleware directory

const app = express();

app.use(myLogger);

app.get('/', (req, res) => {
  res.send('Hello World!');
});

app.listen(3000, () => {
  console.log('Server listening on port 3000');
});"},{"order":10,"type":"paragraph","text":"In this example, 'app.use(myLogger)' applies the 'myLogger' middleware to all routes in the application. Every request will now pass through the 'myLogger' middleware before reaching the route handler."},{"order":11,"type":"code","text":"// Example: Applying middleware at the route level (applies only to specific routes)
const express = require('express');
const myLogger = require('./middleware/myLogger');

const app = express();

app.get('/profile', myLogger, (req, res) => {
  res.send('Profile Page');
});

app.get('/', (req, res) => {
  res.send('Hello World!');
});

app.listen(3000, () => {
  console.log('Server listening on port 3000');
});"},{"order":12,"type":"paragraph","text":"In this example, 'myLogger' is applied only to the '/profile' route. Only requests to '/profile' will pass through the 'myLogger' middleware."},{"order":13,"type":"subheading","text":"Middleware Order"},{"order":14,"type":"paragraph","text":"The order in which you apply middleware is crucial. Middleware functions are executed in the order they are defined. For example, if you have a middleware function that handles authentication, it should be placed before any middleware that requires authentication."},{"order":15,"type":"code","text":"app.use(authenticationMiddleware);
app.use(authorizationMiddleware);
app.get('/protected', (req, res) => {
  res.send('Protected Resource');
});"},{"order":16,"type":"subheading","text":"Types of Middleware"},{"order":17,"type":"bullet_point","text":"Application-level middleware: Bound to the app object using 'app.use()' and applies to all routes."},{"order":18,"type":"bullet_point","text":"Router-level middleware: Bound to 'express.Router()' instances and applies only to routes defined on that router."},{"order":19,"type":"bullet_point","text":"Error-handling middleware: Special middleware functions with four arguments (err, req, res, next) used to handle errors."},{"order":20,"type":"bullet_point","text":"Third-party middleware: Middleware packages available through npm, such as 'body-parser', 'cookie-parser', and 'morgan'."},{"order":21,"type":"subheading","text":"Error-Handling Middleware"},{"order":22,"type":"paragraph","text":"Error-handling middleware functions have four arguments instead of three: '(err, req, res, next)'. Node.js recognizes this signature and knows that this middleware is specifically designed to handle errors. You define error-handling middleware in the same way as other middleware, but you must provide four arguments."},{"order":23,"type":"code","text":"app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});"},{"order":24,"type":"paragraph","text":"This middleware will catch any errors that occur in the preceding middleware or route handlers. It logs the error stack trace and sends a 500 Internal Server Error response to the client."}]
